  "claim": {
    "component_id": "C037.component",
    "value": "If results are inconclusive, the next investigative action should be either repeating the bounded test on later scheduled nights or deploying instrumentation for the unresolved phase.",
    "scope": "Conditional alternative next actions; neither alternative is individually mandatory.",
    "provenance": {
      "refs": [
