          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P031 supplies the inconclusive-results condition and both alternative investigative actions."
    }
  },
  "signal_basis": {
    "component_id": "C037.signal_basis",
    "value": "The bounded concurrency-step test yields inconclusive results: comparisons with baseline and any unchanged pool do not provide adequate evidence, or a phase remains unresolved. Missing phase measurements remain unknown.",
    "scope": "Assume this proposed outcome occurs. Evidence adequacy is assessed against the predeclared observation duration and precision requirement within the safe testing window.",
